package dev.zomboid.decor;
import java.util.*;import dev.zomboid.decor.Checks.*;import net.mcreator.doomsdaydecoration.block.entity.AcrateBlockEntity;import dev.zomboid.survival.MachineEntity;
public class ClimateChecks {
 static int checks;static void ok(boolean b,String message){checks++;if(!b)throw new AssertionError(message);}
 public static class Player {World world;P pos;boolean shift;int messages;Player(World w,P p){world=w;pos=p;}public World level(){return world;}public P blockPosition(){return pos;}public boolean isShiftKeyDown(){return shift;}public void displayClientMessage(Object msg,boolean action){messages++;}}
 public static class Event {World w;P p;Event(World w,P p){this.w=w;this.p=p;}public World getLevel(){return w;}public P getPos(){return p;}}
 public static class Body {private float coreTemperature=2.5f,skinTemperature=.2f,lastSkinTemperature=.2f;}
 public static class Data {float core,skin,last;public void setCoreTemperature(float v){core=v;}public void setSkinTemperature(float v){skin=v;}public void setLastSkinTemperature(float v){last=v;}}
 public static class Env {private float airTemperature=3,localTemperature=3;}
 static AcrateBlockEntity install(World w,P p,String id){State state=new State(id,new Shape(),false);w.states.put(p,state);AcrateBlockEntity be=new AcrateBlockEntity(w,p,state);w.entities.put(p,be);return be;}
 public static void main(String[]a){
  World w=new World();P p=new P(0,64,0),gp=p.offset(20,0,0);AcrateBlockEntity air=install(w,p,"aircondition");MachineEntity gen=new MachineEntity();w.entities.put(gp,gen);MachineEntity.GENERATORS.put(w,new HashSet<>(Set.of(gp)));
  ok(Storage.slots(air).length==0&&!Climate.accepts(air,0,new Checks.Stack("minecraft:iron_ingot","NONE")),"AC cannot silently consume hopper items");Climate.tick(w,air);ok(gen.energy.extracted==400&&gen.changes==1,"actual generator energy deducted and saved");ok(air.ddChill==1&&Climate.active(w,p),"powered device active");Climate.tick(w,air);ok(gen.energy.extracted==400,"duplicate tick cannot charge twice");ok(Climate.active(w,p.offset(15,0,0)),"15 block boundary included");ok(!Climate.active(w,p.offset(16,0,0))&&!Climate.active(w,p.offset(11,11,0)),"sphere excludes outside and diagonal");ok(!Climate.active(new World(),p),"dimensions isolated");
  gen.burn=0;w.time=20;Climate.tick(w,air);ok(air.ddChill==0&&!Climate.active(w,p)&&gen.energy.extracted==400,"fuel loss disables effects despite residual energy");gen.burn=100;gen.energy.stored=399;w.time=40;Climate.tick(w,air);ok(gen.energy.stored==399&&!Climate.active(w,p),"insufficient energy no partial charge");gen.energy.stored=20000;w.time=60;Climate.tick(w,air);ok(Climate.active(w,p),"automatic recovery");air.ddIce=-1;w.time=80;Climate.tick(w,air);ok(!Climate.active(w,p)&&gen.energy.extracted==800,"manual off stops charge");air.ddIce=0;w.time=100;Climate.tick(w,air);w.unloaded.add(p);ok(!Climate.active(w,p),"unloaded AC cannot supply effects");w.unloaded.clear();w.states.remove(p);w.entities.remove(p);ok(!Climate.active(w,p),"removed AC cannot supply effects");
  air=install(w,p,"aircondition");w.time=120;Climate.tick(w,air);Body body=new Body();Player player=new Player(w,p.offset(10,0,0));Climate.homeoBody(player,body);ok(body.coreTemperature==1.6344578f&&body.skinTemperature==body.coreTemperature,"Homeostatic core and skin normalized");Data data=new Data();ok(Climate.homeoData(player,data)&&data.core==1.6344578f&&data.last==data.core,"thermal damage guard normalizes attachment");Env env=new Env();Climate.homeoEnvironment(player,env);ok(env.localTemperature==env.airTemperature&&env.localTemperature<2,"local Homeostatic environment normalized");ok(Climate.tan(player)&&toughasnails.api.temperature.TemperatureHelper.data.hyper==0&&toughasnails.api.temperature.TemperatureHelper.data.level==toughasnails.api.temperature.TemperatureLevel.NEUTRAL,"TAN neutral level and heat debt cleared");player.pos=p.offset(16,0,0);ok(!Climate.homeoData(player,new Data())&&!Climate.tan(player),"temperature outside unaffected");
  // Grow after genuine successful growth. One roll per event regardless of overlapping devices.
  P crop=p.offset(5,0,0);State state=new State("minecraft:wheat",new Shape(),false);state.b=new net.minecraft.world.level.block.CropBlock();state.age=2;w.states.put(crop,state);w.random=new Random(42);int boosted=0;for(int i=0;i<10000;i++){state.age=2;w.states.put(crop,state);Climate.grow(new Event(w,crop));if(w.states.get(crop).age==3)boosted++;}ok(boosted>3350&&boosted<3650,"35 percent successful-growth bonus");
  AcrateBlockEntity second=install(w,p.offset(1,0,0),"airconditioning");Climate.tick(w,second);w.random=new Random(42);int repeated=0;for(int i=0;i<10000;i++){state.age=2;w.states.put(crop,state);Climate.grow(new Event(w,crop));if(w.states.get(crop).age==3)repeated++;}ok(repeated==boosted,"overlap does not stack bonus");state.age=7;w.states.put(crop,state);for(int i=0;i<20;i++)Climate.grow(new Event(w,crop));ok(w.states.get(crop).age==7,"mature crop does not overflow");w.time=1000;ok(!Climate.active(w,crop),"stale power lease expires without ticker");
  for(String id:List.of("desk","desk_2","desk_3","washingmachine","lockers","officepartitiondesk","barrel")){P q=new P(50,64,checks);w.states.put(q,new State(id,new Shape(),false));Storage.repair(w,q);Object be=w.entities.get(q);ok(be instanceof AcrateBlockEntity&&Storage.size(be)>=27,"existing missing inventory repaired: "+id);Storage.repair(w,q);ok(w.entities.get(q)==be,"repair preserves existing inventory: "+id);}
  Object foreign=new Object();P q=new P(100,64,0);w.states.put(q,new State("desk",new Shape(),false));w.entities.put(q,foreign);Storage.repair(w,q);ok(w.entities.get(q)==foreign,"never replace foreign inventory");
  World boards=new World();P window=new P(0,64,0);boards.states.put(window,new State("minecraft:glass",new Shape(),false));ok(Boards.factor(boards,window)==1,"ordinary glass unchanged");boards.states.put(window.offset(1,0,0),new State("planking_0",new Shape(),false));ok(Boards.factor(boards,window)==3,"adjacent boards reinforce glass");ok(dev.zomboid.hordes.BarricadeLink.ticks(100,boards,window)==300,"native AI timer bridge triples break duration");boards.states.put(window,new State("minecraft:stone",new Shape(),false));ok(Boards.factor(boards,window)==1,"stone never receives glass bonus");
  w.time=140;Climate.tick(w,air);player.pos=p;Body viaBody=new Body();dev.zomboid.homeoac.Link.body(player,viaBody);ok(viaBody.coreTemperature==1.6344578f,"Homeostatic patched adapter reaches device logic");Data viaData=new Data();ok(dev.zomboid.homeoac.Link.data(player,viaData)&&viaData.core==1.6344578f,"thermal-check adapter reaches device logic");Env viaEnv=new Env();dev.zomboid.homeoac.Link.environment(player,viaEnv);ok(viaEnv.localTemperature<2,"environment adapter reaches device logic");ok(dev.zomboid.tanac.Link.player(player),"TAN patched adapter reaches device logic");
  gen.burn=0;gen.queued=true;gen.energy.stored=64000;w.time=160;Climate.tick(w,air);ok(gen.energy.stored==63600&&Climate.active(w,p),"full battery with queued fuel cannot deadlock generator refueling");
  for(String id:Climate.AIR)ok(Climate.air(id)&&Storage.IDS.contains(id),"every AC model registered for ticking: "+id);
  System.out.println("CLIMATE_STORAGE_CHECKS="+checks+"; bonus rolls="+boosted+"/10000");
 }
}
